package main

import (
	"bytes"
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"os"
	"os/exec"
	"regexp"
	"sort"
	"strings"
)

// RequestItem represents a single request item (header, field, query param, etc.)
type RequestItem struct {
	itemType string // "field", "header", "query"
	key      string
	value    string
	isJSON   bool // for fields: true if numeric
}

func main() {
	// Handle --help specially to show curl categories
	if len(os.Args) > 1 && os.Args[1] == "--help" {
		showCategories()
		return
	}

	// Parse curlie-specific flags
	showCurl := false
	pretty := false

	// Collect all arguments
	args := os.Args[1:]

	// Look for curlie-specific flags
	var filteredArgs []string
	for i := 0; i < len(args); i++ {
		if args[i] == "--curl" {
			showCurl = true
		} else if args[i] == "--pretty" {
			pretty = true
		} else {
			filteredArgs = append(filteredArgs, args[i])
		}
	}

	// Parse arguments: [curl_options...] [METHOD] URL [items...]
	curlOptions := []string{}
	var method string
	var url string
	var items []RequestItem

	// First, separate curl options from the rest
	i := 0
	for i < len(filteredArgs) {
		arg := filteredArgs[i]

		// If it starts with -, it's likely a curl option
		if strings.HasPrefix(arg, "-") {
			curlOptions = append(curlOptions, arg)
			// Some options take values
			if i+1 < len(filteredArgs) && !strings.HasPrefix(filteredArgs[i+1], "-") {
				// Check if this option takes a value
				if optionTakesValue(arg) {
					i++
					curlOptions = append(curlOptions, filteredArgs[i])
				}
			}
		} else {
			// No more curl options
			break
		}
		i++
	}

	// Now parse METHOD, URL, and items
	remaining := filteredArgs[i:]
	if len(remaining) == 0 {
		showUsage()
		return
	}

	// Check if first remaining is a METHOD
	if isHTTPMethod(remaining[0]) && len(remaining) > 1 {
		method = remaining[0]
		url = remaining[1]
		remaining = remaining[2:]
	} else {
		url = remaining[0]
		remaining = remaining[1:]
	}

	// Parse items
	for _, item := range remaining {
		parsed := parseItem(item)
		if parsed != nil {
			items = append(items, *parsed)
		}
	}

	// Determine HTTP method if not specified
	if method == "" {
		if len(items) > 0 {
			method = "POST"
		} else {
			method = "POST" // Default to POST
		}
	}

	// Build the curl command
	cmd := buildCurlCommand(method, url, items, curlOptions)

	if showCurl {
		fmt.Fprintf(os.Stderr, "%s\n", url)
		fmt.Println(cmd)
		return
	}

	// Execute the command
	executeCurl(cmd, pretty)
}

func showUsage() {
	fmt.Fprintf(os.Stderr, "Usage: %s [options...] [METHOD] URL [REQUEST_ITEM [REQUEST_ITEM ...]]\n", os.Args[0])
	showCategories()
}

func showCategories() {
	fmt.Println("Invalid category provided, here is a list of all categories:")
	categories := map[string]string{
		"auth":       "Different types of authentication methods",
		"connection": "Low level networking operations",
		"curl":       "The command line tool itself",
		"dns":        "General DNS options",
		"file":       "FILE protocol options",
		"ftp":        "FTP protocol options",
		"http":       "HTTP and HTTPS protocol options",
		"imap":       "IMAP protocol options",
		"misc":       "Options that don't fit into any other category",
		"output":     "Filesystem output",
		"pop3":       "POP3 protocol options",
		"post":       "HTTP Post specific options",
		"proxy":      "All options related to proxies",
		"scp":        "SCP protocol options",
		"sftp":       "SFTP protocol options",
		"smtp":       "SMTP protocol options",
		"ssh":        "SSH protocol options",
		"telnet":     "TELNET protocol options",
		"tftp":       "TFTP protocol options",
		"tls":        "All TLS/SSL related options",
		"upload":     "All options for uploads",
		"verbose":    "Options related to any kind of command line output of curl",
	}

	// Sort categories
	var keys []string
	for k := range categories {
		keys = append(keys, k)
	}
	sort.Strings(keys)

	for _, k := range keys {
		fmt.Printf("\n %-12s %s\n", k, categories[k])
	}
}

func isHTTPMethod(s string) bool {
	methods := map[string]bool{
		"GET":     true,
		"POST":    true,
		"PUT":     true,
		"DELETE":  true,
		"PATCH":   true,
		"HEAD":    true,
		"OPTIONS": true,
	}
	return methods[strings.ToUpper(s)]
}

func optionTakesValue(opt string) bool {
	// Options that take a value (these are curl options that consume the next argument)
	valueTakingOptions := map[string]bool{
		"-d": true, "--data": true,
		"-H": true, "--header": true,
		"-u": true, "--user": true,
		"-A": true, "--user-agent": true,
		"-b": true, "--cookie": true,
		"-c": true, "--cookie-jar": true,
		"-o": true, "--output": true,
		"-L": true, "--location": true,
		"-X": true, "--request": true,
	}
	return valueTakingOptions[opt]
}

func parseItem(item string) *RequestItem {
	// Determine item type based on separators
	if strings.Contains(item, "==") {
		// Query parameter
		parts := strings.SplitN(item, "==", 2)
		return &RequestItem{itemType: "query", key: parts[0], value: parts[1]}
	} else if strings.Contains(item, ":=") {
		// JSON numeric field
		parts := strings.SplitN(item, ":=", 2)
		return &RequestItem{itemType: "field", key: parts[0], value: parts[1], isJSON: true}
	} else if strings.Contains(item, ":") {
		// Could be header or JSON field - heuristic
		parts := strings.SplitN(item, ":", 2)
		key := parts[0]
		// If key starts with uppercase and contains no spaces, it's likely a header
		if len(key) > 0 && key[0] >= 'A' && key[0] <= 'Z' {
			return &RequestItem{itemType: "header", key: key, value: parts[1]}
		}
		// Otherwise treat as field
		return &RequestItem{itemType: "field", key: key, value: parts[1], isJSON: false}
	} else if strings.Contains(item, "=") {
		// JSON string field
		parts := strings.SplitN(item, "=", 2)
		return &RequestItem{itemType: "field", key: parts[0], value: parts[1], isJSON: false}
	}
	return nil
}

func buildCurlCommand(method, url string, items []RequestItem, curlOptions []string) string {
	cmd := []string{"curl"}

	// Add curl options first
	cmd = append(cmd, curlOptions...)

	// Add method if not GET
	if method != "GET" {
		cmd = append(cmd, "-X", method)
	}

	// Separate items by type
	var fields map[string]interface{}
	var headers []string
	var queryParams []string

	for _, item := range items {
		switch item.itemType {
		case "field":
			if fields == nil {
				fields = make(map[string]interface{})
			}
			if item.isJSON {
				// Try to parse as number
				var val interface{}
				json.Unmarshal([]byte(item.value), &val)
				fields[item.key] = val
			} else {
				fields[item.key] = item.value
			}
		case "header":
			headers = append(headers, fmt.Sprintf("%s:%s", item.key, item.value))
		case "query":
			queryParams = append(queryParams, fmt.Sprintf("%s=%s", item.key, item.value))
		}
	}

	// Add query parameters to URL
	if len(queryParams) > 0 {
		url = url + "?" + strings.Join(queryParams, "&")
	}

	// Add body if there are fields
	if len(fields) > 0 {
		bodyBytes, _ := json.Marshal(fields)
		cmd = append(cmd, "-d", string(bodyBytes))
	} else {
		cmd = append(cmd, "-d@-")
	}

	// Add URL
	cmd = append(cmd, url)

	// Add standard options
	cmd = append(cmd, "-s", "-S")

	// Add headers
	for _, h := range headers {
		cmd = append(cmd, "-H", h)
	}

	// Add default headers
	cmd = append(cmd, "-H", "Content-Type: application/json", "-H", "Accept: application/json, */*")

	return strings.Join(cmd, " ")
}

func executeCurl(cmdStr string, pretty bool) {
	// Print URL to stderr
	cmd := exec.Command("sh", "-c", cmdStr)

	stdout, _ := cmd.StdoutPipe()
	stderr, _ := cmd.StderrPipe()

	cmd.Start()

	// Read stderr (headers)
	stderrBytes, _ := io.ReadAll(stderr)
	fmt.Fprintf(os.Stderr, "%s\n", string(stderrBytes))

	// Read stdout (body)
	stdoutBytes, _ := io.ReadAll(stdout)

	if pretty && isJSON(stdoutBytes) {
		// Pretty-print JSON
		var obj interface{}
		if err := json.Unmarshal(stdoutBytes, &obj); err == nil {
			prettyBytes, _ := json.MarshalIndent(obj, "", "  ")
			fmt.Println(string(prettyBytes))
		} else {
			fmt.Println(string(stdoutBytes))
		}
	} else {
		fmt.Println(string(stdoutBytes))
	}

	cmd.Wait()
}

func isJSON(data []byte) bool {
	data = bytes.TrimSpace(data)
	if len(data) == 0 {
		return false
	}
	return (data[0] == '{' || data[0] == '[')
}
